/** Official provider app icons (resized to 256px WebP for inline use). */
var PROVIDER_LOGOS = {"navidrome":"data:image/svg+xml;base64,","netease":"data:image/webp;base64,","qq":"data:image/webp;base64,","kugou":"data:image/webp;base64,","kugouLite":"data:image/webp;base64,","bodian":"data:image/webp;base64,","qishui":"data:image/webp;base64,"}

/** Initials for platforms without an official mark in this bundle. */
var PROVIDER_MARKS = {}

function providerLogo(provider, size) {
  var src = PROVIDER_LOGOS[provider]
  if (!src) {
    // A platform without an official mark gets its own initial, not another
    // platform's logo.
    return h(
      'span',
      {
        className: 'mp-provider-logo is-fallback',
        style: {
          width: (size || 20) + 'px',
          height: (size || 20) + 'px',
          fontSize: Math.max(10, Math.round((size || 20) * 0.42)) + 'px',
        },
        'aria-hidden': 'true',
      },
      String(PROVIDER_MARKS[provider] || provider || '?').slice(0, 1).toUpperCase(),
    )
  }
  return h('img', { className: 'mp-provider-logo', src: src, width: size || 20, height: size || 20, alt: '' })
}
